async function saveFragment(){if(!L.available)return error(Error('MZ_DESKTOP_REQUIRED'));inputModal(t('Сохранить монтажный фрагмент','Save timeline fragment'),[{id:'name',label:t('Название','Name'),value:t('Моя заготовка','My fragment'),required:true},{id:'tags',label:t('Теги','Tags')}],async values=>{modal(t('Что сохранится','What will be saved'),t('Сохраним диапазон выделенных клипов со слоями и звуком, попавшими в него. Мини-проект продолжит ссылаться на исходные медиа. Для переноса коллеге их нужно собрать отдельно.','Saves the selected clips’ time range, including layers and audio inside it. The mini-project still references the source media. Collect that media separately when sharing.'),[{label:t('Отмена','Cancel'),run:closeModal},{label:t('Сохранить','Save'),primary:true,run:()=>{closeModal();operation(async()=>{const id=L.id(),path=L.join(L.assetDir(),id+'.prproj'),r=await host('MZ.saveFragment',[path,values.name]);L.addAsset({id,name:values.name,tags:values.tags,path,type:'fragment',duration:r.duration,mediaCollected:false,created:Date.now()});status('Фрагмент сохранён. Содержимое осталось редактируемым.','Fragment saved. Contents remain editable.');render();});}}]);});}
