function renderTools(){const head=topHeading('Инструменты','Everyday tools');$('main').append(head);for(const [key,ru,en,dru,den,ic]of toolDefinitions){if(!matches(ru+' '+en+' '+dru+' '+den))continue;const b=button('',()=>openWorkflow(key),'tool-row'),symbol=el('span','tool-symbol');symbol.innerHTML=svg(ic);const copy=el('span');copy.append(el('strong','',t(ru,en)),el('small','',t(dru,den)));b.append(symbol,copy,el('span','tool-arrow','›'));$('main').append(b);}const external=el('div','info-block');external.style.marginTop='17px';external.append(el('strong','',t('Сторонние плагины','Third-party plugins')),document.createTextNode(t('Парные переходы доступны в разделе «Движение → Переходы». Дополнительные эффекты ищи через «Эффекты Premiere».','Pair transitions are in Motion → Transitions. Use Premiere effects to find installed effects.')));$('main').append(external);}
function openWorkflow(key){W.remember('tool:'+key);if(['native','watch','beats','cut','captions','sync','presets','localtools','modules'].includes(key)){state.screen=key;render();$('main').scrollTop=0;}else if(key==='photo'){modal(t('Подготовить фотографии','Prepare photographs'),t('Scale to Frame Size изменит способ вписывания выделенных клипов. Затем откроется Photo Motion.','Scale to Frame Size changes how selected clips fit the frame. Photo Motion opens afterwards.'),[{label:t('Отмена','Cancel'),run:closeModal},{label:t('Выполнить','Run'),primary:true,run:()=>{closeModal();operation(async()=>{await host('MZ.workflow',['scaleToFrame']);openTool('photo');status('Кадрирование применено. Настрой движение.','Frame scaling applied. Configure motion.');});}}]);}else if(key==='duplicate')operation(async()=>{await host('MZ.workflow',['duplicate']);status('Создана копия секвенции.','Sequence duplicated.');});else renderMacros();}
function reviewMacro(m){const box=el('div');const labels={duplicate:t('Копия секвенции','Duplicate sequence'),scaleToFrame:t('Вписать в кадр','Scale to frame'),save:t('Сохранить проект','Save project')};for(const [i,step]of m.steps.entries())box.append(el('p','',String(i+1)+'. '+(labels[step]||step)));box.append(el('p','help-text',t('При ошибке сценарий остановится. Уже выполненные шаги сохранятся.','A failure stops the workflow. Completed steps remain.')));modal(m.name,box,[{label:t('Отмена','Cancel'),run:closeModal},{label:t('Запустить','Run'),primary:true,run:()=>{closeModal();W.remember('macro:'+m.id);runMacro(m);}}]);}
