function renderNative(){$('main').append(backButton(()=>{state.screen='tools';render();}),topHeading('Эффекты Premiere','Premiere effects'));const search=el('input');search.id='native-search';search.placeholder=t('Название установленного эффекта…','Installed effect name…');const results=el('div','native-results');const populate=()=>{results.replaceChildren();const q=search.value.toLowerCase(),list=nativeNames.filter(n=>n.toLowerCase().includes(q)).slice(0,120);for(const n of list)results.append(button(n,()=>applyNative(n),'native-row'));if(!list.length&&search.value.trim())results.append(button(t('Проверить и применить: ','Find and apply: ')+search.value,()=>applyNative(search.value.trim()),'native-row'));};search.oninput=populate;$('main').append(search,results,button(t('Перечитать список','Refresh list'),async()=>{try{const r=await host('MZ.effects');nativeNames=r.effects;populate();}catch(e){error(e);}},'reference-link'),el('p','help-text',t('Если версия Premiere не отдаёт список, введи точное имя из Effects. Эффект добавляется отдельно от движения ALTO.','If this Premiere version cannot list effects, enter the exact name from Effects. This adds a separate effect.')));populate();if(!nativeNames.length&&window.__adobe_cep__)host('MZ.effects').then(r=>{nativeNames=r.effects;populate();}).catch(()=>{});search.focus();}
