function renderBeats(){$('main').append(backButton(()=>{state.screen='tools';render();}),topHeading('Ритм и паузы','Beats and pauses'));const p=panel();p.append(button(t('Выбрать аудиофайл','Choose audio file'),()=>$('audio-file').click()),el('p','help-text',t('Анализ идёт локально. Исходный звук не отправляется в интернет.','Analysis runs locally. Audio is not uploaded.')));if(state.audio)p.append(el('p','audio-status',state.audio.name+' · '+state.audio.buffer.duration.toFixed(1)+t(' с',' s')));const waveform=el('canvas','waveform');waveform.id='waveform';p.append(waveform);let mode=state.beatMode||'beats',bpm=state.bpm||120,offset=state.beatOffset||0,threshold=state.silenceDb||-35,minPause=state.minPause||.4;p.append(selectField(t('Режим','Mode'),'analysis-mode',[['beats',t('Маркеры по BPM','BPM grid markers')],['silence',t('Найти паузы','Find pauses')]],mode,v=>{state.beatMode=v;render();}));if(mode==='beats'){p.append(field('BPM','beat-bpm',bpm,40,220,.5,v=>{state.bpm=v;state.analysis=null;}),button(t('Оценить BPM по файлу','Estimate BPM from file'),()=>{if(!state.audio)return;state.bpm=estimateBPM(state.audio.buffer);render();status('BPM — приблизительная оценка. Проверь ритм на слух.','BPM is an estimate. Check it by ear.');}));}else p.append(field(t('Порог тишины','Silence threshold'),'silence-db',threshold,-65,-15,1,v=>{state.silenceDb=v;state.analysis=null;},null,' dB'),field(t('Минимальная пауза','Minimum pause'),'silence-min',minPause,.1,2,.05,v=>{state.minPause=v;state.analysis=null;},null,t(' с',' s')));const offsetField=trackField(t('Начало файла на таймлайне, сек.','File start on timeline, seconds'),'beat-offset',offset,v=>state.beatOffset=v);const offsetInput=offsetField.querySelector('input');offsetInput.min=0;offsetInput.step=.01;offsetInput.onchange=()=>{const v=Number(offsetInput.value);if(Number.isFinite(v)&&v>=0){state.beatOffset=v;state.analysis=null;}};p.append(offsetField);p.append(button(t('Посмотреть разметку','Preview markers'),()=>{if(!state.audio)return error(Error('Choose an audio file'));const duration=state.audio.buffer.duration,start=state.beatOffset||0;if((state.beatMode||'beats')==='beats'){const step=60/(state.bpm||120),times=[];for(let a=0;a<duration&&times.length<2000;a+=step)times.push(start+a);state.analysis={times,label:'MZ Beat',mode:'beats'};}else{const pauses=findSilence(state.audio.buffer,state.silenceDb||-35,state.minPause||.4);state.analysis={times:pauses.map(p=>p.start+start),label:'MZ Silence',mode:'silence',pauses};}render();},'apply'));if(state.analysis){p.append(el('p','help-text',state.analysis.times.length+' '+t('маркеров подготовлено.','markers prepared.')),button(t('Добавить маркеры в секвенцию','Add markers to sequence'),()=>operation(async()=>{await host('MZ.markers',[state.analysis.times,state.analysis.label,state.analysis.mode==='beats'?0:1]);status('Маркеры добавлены.','Markers added.');})));}p.append(button(t('Удалить только маркеры ALTO','Remove only ALTO markers'),()=>operation(async()=>{const r=await host('MZ.clearMarkers');status('Удалено маркеров: '+r.count,'Markers removed: '+r.count);}), 'reference-link'));$('main').append(p,el('p','help-text',t('Паузы отмечаются для проверки. Этот инструмент не вырезает речь автоматически. Укажи смещение именно выбранного аудиофайла.','Pauses are marked for review. This tool does not automatically cut speech. Enter the offset of the chosen audio file.')));drawWaveform();}
function drawWaveform(){const canvas=$('waveform');if(!canvas||!state.audio)return;const dpr=window.devicePixelRatio||1,w=canvas.clientWidth||300,h=65;canvas.width=w*dpr;canvas.height=h*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.strokeStyle='#a8adbf';ctx.lineWidth=1;const data=state.audio.buffer.getChannelData(0),step=Math.ceil(data.length/w);ctx.beginPath();for(let x=0;x<w;x++){let peak=0;for(let j=x*step;j<Math.min((x+1)*step,data.length);j+=Math.max(1,Math.floor(step/50)))peak=Math.max(peak,Math.abs(data[j]));ctx.moveTo(x,h/2-peak*h*.45);ctx.lineTo(x,h/2+peak*h*.45);}ctx.stroke();}
function estimateBPM(buffer){const data=buffer.getChannelData(0),size=Math.round(buffer.sampleRate*.01),envelope=[];for(let i=0;i<data.length;i+=size){let e=0;for(let j=i;j<Math.min(i+size,data.length);j++)e+=data[j]*data[j];envelope.push(Math.sqrt(e/size));}const onset=envelope.map((v,i)=>Math.max(0,v-(envelope[i-1]||0)));let best=0,bpm=120;for(let b=60;b<=180;b++){const lag=Math.round(6000/b);let score=0;for(let i=lag;i<onset.length;i++)score+=onset[i]*onset[i-lag];if(score>best){best=score;bpm=b;}}return bpm;}
function findSilence(buffer,db,min){const channels=[];for(let c=0;c<buffer.numberOfChannels;c++)channels.push(buffer.getChannelData(c));const size=Math.round(buffer.sampleRate*.02),threshold=Math.pow(10,db/20),result=[];let start=null;for(let i=0;i<buffer.length;i+=size){let sum=0,count=0;for(const data of channels)for(let j=i;j<Math.min(i+size,data.length);j++){sum+=data[j]*data[j];count++;}const silent=Math.sqrt(sum/count)<threshold,time=i/buffer.sampleRate;if(silent&&start===null)start=time;if(!silent&&start!==null){if(time-start>=min)result.push({start,end:time});start=null;}}if(start!==null&&buffer.duration-start>=min)result.push({start,end:buffer.duration});return result;}
function renderCamera(){window.AltoCamera.render(window.MZUI,{stops:cameraStops,options:cameraOptions,bind:bindCamera,capture:captureTimelineFrame,apply:applyCamera,load:()=>{state.referenceFor='camera';$('reference-file').click();},update:updateCameraRoute,draw:drawCamera});}
function cameraAvailable(){const i=state.cameraInfo;if(!i)return null;let offset=0;if(state.cameraStart==='playhead'){if(i.playhead<i.start||i.playhead>=i.end)throw Error('Playhead must be inside layer');offset=Math.max(0,Math.ceil((i.playhead-i.start)/i.frame-.000001));}return Math.floor(i.duration/i.frame-1+.000001)-offset;}
function updateCameraRoute(){try{const opts=Object.assign({},cameraOptions,{fitFrames:cameraOptions.fit?cameraAvailable():null});state.cameraRoute=MZEngine.camera(cameraStops,opts,state.cameraInfo?state.cameraInfo.fps:25);AltoTimeline.focus(cameraStops,state.cameraRoute);if($('camera-summary'))$('camera-summary').textContent=cameraStops.length+t(' ракурса · ',' views · ')+state.cameraRoute.seconds.toFixed(2)+t(' с · ',' s · ')+state.cameraRoute.keys.length+t(' точек кривой',' curve points');}catch(e){state.cameraRoute=null;if($('camera-summary'))$('camera-summary').textContent=String(e.message||e);}drawCamera();}
function drawCamera(){const map=$('camera-map'),art=$('camera-art'),markers=$('camera-markers'),frame=$('camera-window');if(!map||!art)return;const moving=(state.cameraPlaying||state.cameraScrubbing)&&state.cameraRoute;if(moving){const p=MZMotion.sample(state.cameraRoute,state.cameraTime*state.cameraRoute.fps);art.style.transform='translate('+((p.x-.5)*map.clientWidth)+'px,'+((p.y-.5)*map.clientHeight)+'px) scale('+(p.scale/100)+')';markers.hidden=true;frame.hidden=true;}else{art.style.transform='none';markers.hidden=false;frame.hidden=false;markers.replaceChildren();cameraStops.forEach((s,i)=>{const b=button(String(i+1),e=>{e.stopPropagation();state.cameraIndex=i;state.cameraPlaying=false;state.cameraScrubbing=false;render();},'marker'+(i===state.cameraIndex?' selected':''));b.style.left=s.fx*100+'%';b.style.top=s.fy*100+'%';b.setAttribute('aria-label',t('Ракурс ','View ')+(i+1));markers.append(b);});const s=cameraStops[state.cameraIndex],p=MZMotion.pose(s,cameraOptions.protect),scale=p.scale/100;frame.style.left=(.5+(.5-p.x)/scale)*100+'%';frame.style.top=(.5+(.5-p.y)/scale)*100+'%';frame.style.width=100/scale+'%';frame.style.height=100/scale+'%';}if($('camera-scrub')){$('camera-scrub').value=state.cameraRoute?state.cameraTime/state.cameraRoute.seconds:0;window.AltoSurfaces.update($('camera-scrub'));}}
async function captureTimelineFrame(){await operation(async()=>{
 status('Захватываю кадр из Premiere…','Capturing a Premiere frame…');let ticket=null;
 try{
  let frame=await host('MZ.captureTimelineFrame');ticket=frame.ticket;
  const deadline=performance.now()+5500;
  while(frame.pending){if(performance.now()>deadline)throw Error('MZ_FRAME_EXPORT_FAILED');await new Promise(resolve=>setTimeout(resolve,150));frame=await host('MZ.pollTimelineFrame',[ticket]);}
  const data=L.frameDataURL(frame);
  await new Promise((resolve,reject)=>{const image=new Image(),timeout=setTimeout(()=>reject(Error('MZ_FRAME_READ')),5000);image.onload=()=>{clearTimeout(timeout);if(image.naturalWidth!==frame.width||image.naturalHeight!==frame.height)return reject(Error('MZ_FRAME_DIMENSIONS'));resolve();};image.onerror=()=>{clearTimeout(timeout);reject(Error('MZ_FRAME_INVALID_PNG'));};image.src=data;});
  const info=await host('VMV.cameraInfo').catch(()=>null);
  state.cameraImage=data;state.cameraFrame={width:frame.width,height:frame.height,sequenceID:frame.sequenceID,ticks:frame.ticks,timecode:frame.timecode};
  state.cameraInfo=info&&info.binding.sequenceID===frame.sequenceID?info:null;state.cameraPlaying=false;state.cameraScrubbing=false;
  if(state.screen==='camera')render();status('Кадр с таймлайна загружен · '+frame.timecode,'Timeline frame captured · '+frame.timecode);
 }finally{if(ticket)await host('MZ.discardTimelineFrame',[ticket]).catch(()=>{});const b=$('capture-timeline-frame');if(b)b.disabled=false;}
});}
