function bufferOf(file){if(file.arrayBuffer)return file.arrayBuffer();return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('File read failed'));r.readAsArrayBuffer(file);});}
$('asset-files').onchange=async e=>{const files=Array.from(e.target.files);await operation(async()=>{for(const f of files){if(!f.path)throw Error('MZ_DESKTOP_REQUIRED');L.importAsset(f);}status('Добавлено материалов: '+files.length,'Assets added: '+files.length);render();});e.target.value='';};
$('reference-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024){error(Error('Image exceeds 20 MB'));return;}const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{if(img.width*img.height>80000000)return error(Error('Image exceeds 80 megapixels'));if(state.referenceFor==='camera'||state.screen==='camera'){if(state.cameraInfo&&Math.abs(img.width/img.height-state.cameraInfo.width/state.cameraInfo.height)>.01){modal(t('Пропорции кадра отличаются','Reference aspect ratio differs'),t('Экспортируй общий кадр из той же секвенции. Сейчас точки не будут совпадать с таймлайном.','Export an overview frame from the same sequence. These reference points would not match the timeline.'),[{label:t('Понятно','Got it'),run:closeModal}]);return;}state.cameraImage=r.result;state.cameraFrame=null;}else state.reference=r.result;state.referenceFor=null;render();};img.onerror=()=>error(Error('Cannot decode image'));img.src=r.result;};r.readAsDataURL(f);e.target.value='';};
$('audio-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;await operation(async()=>{if(f.size>100*1024*1024)throw Error('Audio exceeds 100 MB');const ctx=new (window.AudioContext||window.webkitAudioContext)();try{const buffer=await ctx.decodeAudioData(await bufferOf(f));state.audio={name:f.name,buffer};state.analysis=null;render();status('Аудио прочитано. Настрой разметку.','Audio loaded. Configure markers.');}finally{await ctx.close();}});e.target.value='';};
$('update-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;await operation(async()=>{if(!L.available)throw Error('MZ_DESKTOP_REQUIRED');if(f.size>64*1024*1024)throw Error('Update exceeds 64 MB');const bytes=(window.require||require)('buffer').Buffer.from(await bufferOf(f));const staged=L.stageUpdate(bytes,extensionPath());status('Подготовлена версия '+staged.version,'Version '+staged.version+' staged');render();});e.target.value='';};
$('preset-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;await operation(async()=>{if(f.size>1024*1024)throw Error('Preset file exceeds 1 MB');const bytes=await bufferOf(f),text=new TextDecoder('utf-8').decode(bytes),data=JSON.parse(text);if(data.format!=='montazhopa-presets'||!Array.isArray(data.presets)||data.presets.length>200)throw Error('Invalid preset format');const clean=data.presets.map(p=>{if(!C.some(c=>c.id===p.kind&&c.id!=='camera')||typeof p.name!=='string'||p.name.length>160)throw Error('Invalid preset');if(state.importCategory&&C.find(c=>c.id===p.kind).group!==state.importCategory)throw Error(t('Файл содержит пресет другой категории. Открой подходящую категорию.','The preset belongs to another category. Open that category first.'));return {id:'variant-'+L.id(),kind:p.kind,name:p.name,options:MZEngine.options(p.options)};});L.write('variants.json',L.read('variants.json',[]).concat(clean));status('Импортировано вариантов: '+clean.length,'Presets imported: '+clean.length);state.importCategory=null;render();});e.target.value='';};
