document.addEventListener('keydown',e=>{if(!$('modal').hidden){if(e.key==='Escape'){const cancel=Array.from($('modal-actions').children).find(b=>/^(Нет|No|Отмена|Cancel|Закрыть|Close|Понятно|Got it)$/.test(b.textContent));if(cancel)cancel.click();else closeModal();e.preventDefault();}if(e.key==='Tab'){const focusable=Array.from($('modal').querySelectorAll('input,select,button,[tabindex]')).filter(x=>!x.disabled);if(focusable.length){const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}return;}if(e.key==='Escape'&&!$('search-wrap').hidden){$('search-close').click();return;}if((e.ctrlKey||e.metaKey)&&(e.key.toLowerCase()==='f'||e.key.toLowerCase()==='k')){e.preventDefault();$('search-wrap').hidden=false;render();$('search').focus();}if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){e.preventDefault();$('search-wrap').hidden=false;render();$('search').focus();}});
function showTooltip(target){if(!target.isConnected)return;const text=target.dataset.tip;if(!text)return;const tip=$('tooltip');tip.textContent=text;tip.hidden=false;const r=target.getBoundingClientRect(),rect=tip.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(innerWidth-rect.width-8,r.left))+'px';tip.style.top=(r.bottom+rect.height+10<innerHeight?r.bottom+7:Math.max(7,r.top-rect.height-7))+'px';}
