function tick(now){const dt=Math.min(.05,(now-last)/1000);last=now;if(!document.hidden){if(state.screen==='detail'&&state.playing){state.elapsed+=dt;drawDetail();}if(state.hover){const h=state.hover,u=Math.min(1,((now-state.hoverAt)/1000%1.65)/.9);drawArt(h.art,h.kind,h.opts,u,h.thumb.clientWidth,h.thumb.clientHeight);}if(state.screen==='camera'&&state.cameraPlaying&&state.cameraRoute){state.cameraScrubbing=false;state.cameraTime=(state.cameraTime+dt)%(state.cameraRoute.seconds+.7);drawCamera();}}animationFrame=requestAnimationFrame(tick);}
